import pathlib,json,statistics,subprocess,shlex
p=pathlib.Path(__file__).resolve().parent; scope=json.loads((p/'scope.json').read_text()); tests=scope['tests']; base=scope['base']; witness={'TestEnumNameEnumerationMutant':'W1','TestEnumSemanticMutants':'W1','TestEnumCleanupMutant':'W2','TestFallthroughMutants':'W1','TestFieldReadinessRepresentation':'W1'}; production=[t for t in tests if t not in witness]
def events(name):return [json.loads(s) for s in (p/(name+'.log')).read_text().splitlines() if s.startswith('{')]
def status(name,t):
 es=events(name); finished=[e['Action'] for e in es if e.get('Test')==t and e['Action'] in ['pass','fail','skip']]
 if finished:return finished[-1]
 if name.startswith('P1-isolated-') and any('panic:' in e.get('Output','') for e in es):return 'fail (isolated panic)'
 return 'unknown'
def fail_line(name,t):
 es=events(name); candidates=[e.get('Output','').strip() for e in es if e.get('Test','').split('/')[0]==t and e['Action']=='output' and ': ' in e.get('Output','') and not any(s in e.get('Output','') for s in ['gate cache','===','---','PASS','FAIL','caught only','caught by Node','drop field check'])]
 if candidates:return candidates[0]
 return next((e['Output'].strip() for e in es if 'panic:' in e.get('Output','')),'no failing diagnostic recorded')
commands=json.loads((p/'commands.json').read_text()); byname={c['label']:c for c in commands}
def command(name):
 c=byname[name]; env='ADAMIC_MUTANT='+name+' ADAMIC_BUILD_CACHE_DIR=/tmp/u060/cache/'+name+' ADAMIC_GATE_UNCACHED=1 '
 return env+shlex.join(c['command'])+' > review/test-audit/internal-oracle-enums_open/'+name+'.log 2>&1'
seconds={}; runs={}
for t in tests:
 values=[]
 for i in [1,2,3]:values.append(next(e['Elapsed'] for e in reversed(events('timing-'+t+'-'+str(i))) if e['Action']=='pass' and not e.get('Test')))
 runs[t]=values; seconds[t]=statistics.median(values)
matrix={n:{t:status(n,t) for t in tests} for n in ['M1','M2','M3','M4','P2','P3']}; matrix['P1']={t:status('P1-isolated-'+t,t) for t in tests}; matrix['W1']={t:status('W1',t) for t,w in witness.items() if w=='W1'}; matrix['W2']={'TestEnumCleanupMutant':status('W2','TestEnumCleanupMutant')}
for name in ['M1','M2','M3','M4']:assert all(matrix[name][t] in ['pass','fail'] for t in tests)
(p/'matrix.json').write_text(json.dumps({'bounded':True,'matrix_rows':tests,'production_verdict_rows':production,'observations':matrix,'witness_production_failures_excluded':True,'P1_observations':'isolated runs supersede aborted aggregate run'},indent=2)+'\n')
killsets={t:[n for n in ['M1','M2','M3','M4'] if matrix[n][t]=='fail'] for t in production}; unique={n:[t for t in production if n in killsets[t]] for n in ['M1','M2','M3','M4']}
oracles={
'TestNumericEnumNeverPathsPinned':('Self-pinned before/lookup stdout, numeric-enum panic stderr and exit 70; native and JavaScript must match the full triple.','self'),
'TestNumericEnumNeverPinned':('Self-pinned Adamic panic triple; separately runs source on Node and checks its successful stdout.',['self','external-run']),
'TestStage3EnumBoundaries':('TypeScript-Go checker errors must have TS2532; Adamic refusal must have invariant-mutable. Error class plus substring only, not full diagnostic location.',['external-run','self']),
'TestStage3EnumSparseArrayBoundary':('Self-pinned native and JavaScript array-bounds panic triple. Node side checks only successful exit, not its stdout.',['self','external-run']),
'TestEnumNameEnumerationMutant':('Actual Node source stdout comparison must detect built-in enum-field order swap.','external-run'),
'TestEnumSemanticMutants':('Actual Node source stdout comparison must detect six built-in semantic mutants after clean native exits.','external-run'),
'TestEnumCleanupMutant':('LeakSanitizer must detect omitted cleanup, while actual Node stdout remains unchanged.','external-run'),
'TestFallthroughMutants':('Actual Node stdout comparisons for isolated cases and continue-as-break; self-pinned compiler missing-return panic for the third subcase.',['external-run','self']),
'TestFieldReadinessRepresentation':('Self-pinned readiness panic and written zero; built-in removed-readiness mutant must disagree. No external authority.','self'),
'TestFreshWriteProbesStayRefused':('Self-pinned marked cycle-write site and adamic/cycle-capable label. Node and leak checks run only if lowering accepts a probe. M3 catches removal of the label, not acceptance of a cycle.','self'),
'TestFunctionValueBoundaryBoxing':('Self-pinned successful lowering, four callable arguments and boxed union return shapes. M2 fails during Lower with NotYet, before the structural assertions; those individual assertions remain unproven.','self'),
'TestImportCycleRuntimeCalls':('Actual independent Node runner invokes exports after module bodies; compares full result triples to native, released native and generated JavaScript, plus leak checks.','external-run'),
'TestImportCycleLoadTimeReads':('Actual Node source stdout, stderr and exit comparisons, with fixture preconditions for initialization errors.','external-run'),
'TestImportedNonliteralConstCaseIsNotYet':('Actual Node source succeeds with pinned stdout; Adamic NotYet type, path, position and full wording are self-pinned.',['external-run','self']),
'TestInputAgreesWithNode':('Actual Node source triples plus written file names, bytes and permissions; native and JavaScript must agree, with explicit permission-denial checks and leak checks.','external-run')}
rows=[]
for t in tests:
 file=next(str(f) for f in pathlib.Path('internal/oracle').glob('*_test.go') if 'func '+t+'(' in f.read_text()); source=subprocess.check_output(['git','show',base+':'+file],text=True); line=next(i for i,l in enumerate(source.splitlines(),1) if 'func '+t+'(' in l)
 kills=killsets.get(t,[]); uniques=[n for n in kills if len(unique[n])==1]; subs=[]; subsseconds=None
 if t in witness:
  verdict='witness'; name=witness[t]; assert matrix[name][t]=='fail'; probe=[]; vacuous=None; matrixrows=list(matrix[name])
 else:
  name=kills[-1]; verdict='sacred' if uniques else 'subsumed'; candidates=[other for other in production if other!=t and set(kills)<=set(killsets[other])]
  if not uniques:
   assert kills and candidates; sub=min(candidates,key=lambda x:seconds[x]); subs=[sub]; subsseconds=seconds[sub]
  probe=['P1']; assert matrix['P1'][t].startswith('fail'); vacuous=False; matrixrows=tests
  if t in ['TestNumericEnumNeverPathsPinned','TestNumericEnumNeverPinned','TestStage3EnumSparseArrayBoundary','TestImportCycleRuntimeCalls','TestImportCycleLoadTimeReads','TestInputAgreesWithNode']:
   probe += [n for n in ['P2','P3'] if matrix[n][t]=='fail']
 row={'test':t,'package':'internal/oracle','file':file+':'+str(line),'seconds':seconds[t],'oracle':oracles[t][0],'oracle_kind':oracles[t][1],'kills':kills,'unique_kills':uniques,'last_proven_fail':name+': '+fail_line(name,t),'verdict':verdict,'subsumed_by':subs,'mutants_in_matrix':0 if t in witness else 4,'probe_kills':probe,'subsumer_seconds':subsseconds,'vacuous':vacuous,'bounded':True,'matrix_rows':matrixrows,'evidence':command(name)+'; '+fail_line(name,t)}
 if t in witness:row['witness_kills']=[name]
 if t=='TestStage3EnumBoundaries':row['probe_scope']='Lower subcase only; two checker-error subcases did not reach Lower and were not entry-probed.'
 rows.append(row)
(p/'rows.json').write_text(json.dumps(rows,indent=2)+'\n'); (p/'timings.json').write_text(json.dumps({'nproc':5,'setup_seconds':0,'npm_reported_seconds':0.438,'runs':runs,'medians':seconds,'switch_go_compile_seconds':byname['switch-compile']['seconds'],'matrix_wall_seconds':{n:byname[n]['seconds'] for n in ['M1','M2','M3','M4','P1','P2','P3','W1','W2']},'representative_native_rebuilds':json.loads((p/'native-rebuilds.json').read_text())},indent=2)+'\n')
skips=[e.get('Test') for e in events('baseline') if e['Action']=='skip']; (p/'skipped.json').write_text(json.dumps({'assigned':[],'whole_baseline_observed_skips':skips},indent=2)+'\n')
summary=['u060: all 15 assigned names exist; no families, moves or vanished functions.','Base: '+base+'.','Bounded verdicts: 2 sacred, 8 subsumed, 5 witness.','All ten production rows rejected their Lower probe; witness vacuity was not judged by production probes.','Evidence: review/test-audit/internal-oracle-enums_open/ on test-audit/internal-oracle-enums_open.','', '```json',json.dumps(rows,indent=2),'```','', '| ID | File:line at base | Change | Observed top-level failures |','|---|---|---|---|']
changes=[('M1','internal/native/emit.go:106','drop emitter.block(program.Main, nil)'),('M2','internal/lower/expression.go:684','flip union boxing value.Type() != ir.Union to =='),('M3','internal/lower/diagnostics.go:29','final Refused format %s to %.0s, hiding Fix'),('M4','internal/lower/diagnostics.go:17','NotYet suffix yet to now'),('W1','internal/oracle/oracle_test.go:716','disagreement returns empty; witness-only harness weakening'),('W2','internal/oracle/oracle_test.go:512','force ASAN_OPTIONS=detect_leaks=0; witness-only harness weakening'),('P1','internal/lower/lower.go:20','Lower returns nil,nil; probe'),('P2','internal/native/emit.go:22','C returns empty string; probe'),('P3','internal/javascript/javascript.go:24','JavaScript returns empty string; probe')]
for n,file,change in changes:summary.append('| '+n+' | '+file+' | '+change+' | '+', '.join(t for t,s in matrix[n].items() if s.startswith('fail'))+' |')
summary += ['','Survivors: none among the four production mutations in the bounded matrix. M1 witness failures are broken preconditions and are excluded from kill sets. W1/W2 and probes are excluded from production kills and uniqueness.','', 'Brief ambiguities, costs and limitations:','', '- The old file reference is 8de93800f4; the required fresh main was '+base+'. Every line reference is against this actual base. All 15 names exist and remain in the named files.','- The whole-package baseline consumed 90.146 seconds without a preceding test failure, then timed out. The target slice passed clean with coverage in 6.476 seconds, and restored source passed with ADAMIC_GATE_UNCACHED=1 in 8.328 seconds. A completed whole-package baseline and kills outside the assigned slice remain unknown.','- The package is the oracle harness, while the production code under test is lowering and the backends. Mutating disagreement is permitted only for witnesses. Node, TypeScript-Go and LeakSanitizer were not changed; W2 changes harness detector configuration only.','- Five rows contain built-in mutants. Their failures under M1 are not proof that their guard works. W1 makes all four relevant witnesses fail; W2 makes cleanup fail. Fallthrough missing_implicit_return passes W1, because it guards a different runtime panic and does not call disagreement. That guard was not separately weakened.','- Four compiler mutants were used under the rebuild cap, rather than attempting the conflicting approximate three-per-row target. Two are diagnostic mutations. M3 proves refusal-label checking, not refusal safety; M4 proves wording checking. No cycle-proof guard was disabled.','- Six ordinary rows have only M1 in their kill set, and two have only M3. Their subsumption verdicts rest on one coarse mutant each. M1 drops a main emission call but retains C assembly, function bodies and global cleanup, so it is distinct from the empty-C probe. These small-set results are hints, not deletion recommendations.','- M2 is unique to the boxing row but is caught by Lower returning NotYet before its IR assertions. This proves that the row rejects that lowering regression. It cannot prove the individual argument/return shape assertions can fail.','- Fresh refusal runs do not actually run Node; the Node and leak branch runs only after unexpected acceptance. They are self-oracled. SparseArrayBoundary checks only Node exit success, while the Adamic panic expectation compares the full result triple. Stage3 checker cases check error class and code substring, not a full diagnostic location.','- Nil Lower aborts the binary. Every assigned row was rerun alone, and matrix.json uses only these isolated P1 observations. FieldReadiness does not call Lower, so its P1 pass is not a vacuity finding. Witness vacuity is null because their comparison/detector entry was judged through weakening, not a separate production entry probe.','- Empty C is rejected by native compilation/linking before runtime assertions; empty JavaScript actually runs as an empty module. These are probes only. Stage3 boundaries probe only the Lower subcase; the two upstream checker-error subcases do not reach Lower.','- Standalone early-return probes and W1 initially failed go vet for unreachable code. Their replay diffs now replace the unused bodies, with the same evaluated return behavior. Lower also drops the two imports used only by its removed body. Drafts and failed vet logs remain labeled evidence; all final replay diffs pass go vet.','- A validation call initially omitted env.sh and invoked a different go command. Those invalid-environment outputs were excluded, preserved separately, and all checks were rerun with the required toolchain.','- Go coverage records 698 reached functions across load/lower/native/javascript. It does not enumerate runtime C function coverage. Clean timings permit normal oracle caches; matrices and witness runs disable observation caches. Timings therefore describe normal warm invocation cost, not fully cold execution.','- Native rebuild measurements are for one representative enum fixture per variant, not the sum of all fixture builds in each matrix run. Matrix wall times include remaining builds and execution; those two components were not separately instrumented.','', 'Setup: warm env.sh worked; no setup install; nproc 5. npm ci reported 0.438 seconds. Shared switched Go test compilation took 11.398 seconds. Representative native.Build times: M1 0.169s, M2 0.159s, M3 0.154s, M4 0.161s. Exact per-row three-run medians, matrix wall times, command exits and isolated-probe durations are preserved in timings.json and commands.json.','', 'Not covered: other packages, full-package/repository uniqueness, exhaustive mutation coverage, fresh cycle acceptance, boxing assertion branches under a successful mutated Lower, Fallthrough missing-return witness weakening, upstream checker entry probes and C call coverage. Production sources were restored. No main push or pull request.']
